-- AC-SAME v3 (27/10, Guillaume): the CAMO scope does not change for a type already operated, but the CAME (fleet list) and the AMP
-- do — both revised and approved for every aircraft. Taken from the 9H-ASJ Monday board.
insert into project_templates (code, name, description, entities, phases, tasks, pivots, ord, active) values
('AC-SAME', 'Aircraft addition — type already operated', 'One more aircraft of a type already on the AOC: contract, inspection and documents, registration, CofA, radio, insurance; CAME and AMP revised (the registration is listed in both) and approved; MEL / OM-B / EFB specifics; one operations specifications variation. The CAMO scope itself does not change.', array['AJD','ASJ']::entity_code[],
 '[{"key": "frame", "label": "1 · Decide"}, {"key": "acft", "label": "2 · Aircraft & documents"}, {"key": "aw", "label": "3 · Airworthiness"}, {"key": "app", "label": "4 · Applications"}, {"key": "eis", "label": "5 · Entry into service"}]'::jsonb,
 '[{"key": "contract", "phase": "frame", "title": "Management / lease contract signed", "owner_role": "AM", "days": 5, "deps": []}, {"key": "moc", "phase": "frame", "title": "MOC + risk assessment", "owner_role": "SM", "days": 2, "deps": ["contract"]}, {"key": "ppi", "phase": "acft", "title": "Pre-purchase inspection and records review", "owner_role": "NPCA", "days": 5, "deps": ["contract"]}, {"key": "ctrl", "phase": "acft", "title": "Control flight after the inspection", "owner_role": "NPFO", "days": 1, "deps": ["ppi"]}, {"key": "typedocs", "phase": "acft", "title": "Type documents for this aircraft: AFM, MMEL, O&M", "owner_role": "CMM", "days": 1, "deps": ["contract"]}, {"key": "reg", "phase": "acft", "title": "Registration", "owner_role": "NPCA", "days": 10, "deps": ["contract"], "link_kind": "authority_file", "link_ref": "AW-CERT"}, {"key": "cofa", "phase": "acft", "title": "Certificate of Airworthiness / ARC", "owner_role": "NPCA", "days": 10, "deps": ["reg", "ppi"], "link_kind": "certificate", "link_ref": "CofA"}, {"key": "radio", "phase": "acft", "title": "Radio licence", "owner_role": "NPCA", "days": 5, "deps": ["reg"], "link_kind": "certificate", "link_ref": "radio"}, {"key": "insur", "phase": "acft", "title": "Insurance", "owner_role": "NPGO", "days": 5, "deps": ["contract"], "link_kind": "certificate", "link_ref": "insurance"}, {"key": "came", "phase": "aw", "title": "CAME — registration added to the fleet list", "owner_role": "NPCA", "days": 5, "deps": ["contract"], "link_kind": "manual", "link_ref": "CAME"}, {"key": "amp", "phase": "aw", "title": "AMP — registration added", "owner_role": "NPCA", "days": 5, "deps": ["ppi"], "link_kind": "manual", "link_ref": "AMP"}, {"key": "ide", "phase": "aw", "title": "CAT IDE checklist (CAD 0202) for this aircraft", "owner_role": "NPCA", "days": 4, "deps": ["ppi"]}, {"key": "app_came", "phase": "aw", "title": "CAME approval", "owner_role": "CMM", "days": 1, "deps": ["came"], "link_kind": "authority_file", "link_ref": "CAME"}, {"key": "app_amp", "phase": "aw", "title": "AMP approval", "owner_role": "CMM", "days": 1, "deps": ["amp"], "link_kind": "authority_file", "link_ref": "AMP"}, {"key": "mel", "phase": "app", "title": "MEL / OM-B / EFB — registration and configuration specifics", "owner_role": "NPFO", "days": 3, "deps": ["typedocs"], "link_kind": "manual", "link_ref": "MEL"}, {"key": "crew", "phase": "app", "title": "Crew licences, medicals and SPA training recorded", "owner_role": "NPCT", "days": 10, "deps": ["contract"]}, {"key": "app", "phase": "app", "title": "Operations specifications variation — addition of the aircraft", "owner_role": "CMM", "days": 1, "deps": ["reg", "cofa", "insur", "mel", "app_came", "app_amp"], "link_kind": "authority_file", "link_ref": "AC-SAME"}, {"key": "opspecs", "phase": "eis", "title": "Operations specifications received", "owner_role": "CMM", "days": 1, "deps": ["app"], "link_kind": "certificate", "link_ref": "OpSpecs"}, {"key": "systems", "phase": "eis", "title": "Fleet systems live (Leon, EFB, FDM, TrustFlight), crews informed", "owner_role": "NPFO", "days": 2, "deps": ["opspecs"]}]'::jsonb,
 array['aircraft_type','aircraft_reg']::text[], 2, true)
on conflict (code) do update set name = excluded.name, description = excluded.description, entities = excluded.entities, phases = excluded.phases, tasks = excluded.tasks, pivots = excluded.pivots;
